import "./styles.css";

import { BaseText } from "@components/BaseText";
import ErrorBoundary from "@components/ErrorBoundary";
import { Devs } from "@utils/constants";
import { getCurrentChannel } from "@utils/discord";
import definePlugin from "@utils/types";
import { findByCodeLazy, findByPropsLazy, findComponentByCodeLazy, findCssClassesLazy } from "@webpack";
import { RelationshipStore } from "@webpack/common";

const WrapperClasses = findCssClassesLazy("memberSinceWrapper");
const ContainerClasses = findCssClassesLazy("memberSince");
const getCreatedAtDate = findByCodeLazy('month:"short",day:"numeric"');
const locale = findByPropsLazy("getLocale");
const Section = findComponentByCodeLazy("headingVariant:", '"section"', "headingIcon:");

const FriendsSinceSection = ErrorBoundary.wrap(({ userId, isSideBar }: { userId: string; isSideBar: boolean; }) => {
    if (!RelationshipStore.isFriend(userId)) return null;

    const friendsSince = RelationshipStore.getSince(userId);
    if (!friendsSince) return null;

    if (isSideBar) {
        return (
            <Section
                heading="Friends Since"
                headingVariant="text-xs/semibold"
                headingColor="text-strong"
            >
                <BaseText size="sm">
                    {getCreatedAtDate(friendsSince, locale.getLocale())}
                </BaseText>
            </Section>
        );
    }

    return (
        <Section
            heading="Friends Since"
            headingVariant="text-xs/medium"
            headingColor="text-default"
            className="vc-friendsSince-profile-section"
        >
            <div className={WrapperClasses.memberSinceWrapper}>
                <div className={ContainerClasses.memberSince}>
                    {!!getCurrentChannel()?.guild_id && (
                        <svg
                            aria-hidden="true"
                            width="16"
                            height="16"
                            viewBox="0 0 24 24"
                            fill="var(--interactive-icon-default)"
                        >
                            <path d="M13 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z" />
                            <path d="M3 5v-.75C3 3.56 3.56 3 4.25 3s1.24.56 1.33 1.25C6.12 8.65 9.46 12 13 12h1a8 8 0 0 1 8 8 2 2 0 0 1-2 2 .21.21 0 0 1-.2-.15 7.65 7.65 0 0 0-1.32-2.3c-.15-.2-.42-.06-.39.17l.25 2c.02.15-.1.28-.25.28H9a2 2 0 0 1-2-2v-2.22c0-1.57-.67-3.05-1.53-4.37A15.85 15.85 0 0 1 3 5Z" />
                        </svg>
                    )}
                    <BaseText size="sm">
                        {getCreatedAtDate(friendsSince, locale.getLocale())}
                    </BaseText>
                </div>
            </div>
        </Section>
    );
}, { noop: true });

export default definePlugin({
    name: "FriendsSince",
    description: "Shows when you became friends with someone in the user popout",
    tags: ["Friends"],
    authors: [Devs.Elvyra, Devs.Antti],
    dependencies: ["ProfileSectionsAPI"],
    renderProfileSection: {
        render: FriendsSinceSection,
        priority: 0,
    },
});
