// ── Helpers ────────────────────────────────────────────────────────────────────

// DataStore keys used by the customProfile plugin
const CP_DS_ALL_DATA = "customProfile_allData";
const CP_DS_KEY      = "customProfile_data";

async function readCustomProfileDataAsync(userId: string): Promise<Record<string, any> | null> {
    // Primary: DataStore (IndexedDB) — this is where customProfile actually persists data
    try {
        const allData = await DataStore.get(CP_DS_ALL_DATA) as Record<string, any> | null;
        if (allData && typeof allData === "object") {
            const entry = allData[userId];
            if (entry && typeof entry === "object" && Object.keys(entry).length > 0) {
                console.log("[bleedsSync] readCP: DataStore allData found for", userId, entry);
                return entry;
            }
        }
    } catch (e) {
        console.warn("[bleedsSync] DataStore allData read failed:", e);
    }

    try {
        const single = await DataStore.get(CP_DS_KEY) as Record<string, any> | null;
        if (single && typeof single === "object" && Object.keys(single).length > 0) {
            console.log("[bleedsSync] readCP: DataStore single found", single);
            return single;
        }
    } catch (e) {
        console.warn("[bleedsSync] DataStore single read failed:", e);
    }

    // Fallback: localStorage (may be empty/unavailable in some setups)
    try {
        const rawAll = localStorage.getItem("BleedsCP_allData");
        if (rawAll) {
            const all = JSON.parse(rawAll);
            const entry = all[userId];
            if (entry && typeof entry === "object" && Object.keys(entry).length > 0) {
                console.log("[bleedsSync] readCP: localStorage allData found", entry);
                return entry;
            }
        }
        const rawSingle = localStorage.getItem("BleedsCP_data");
        if (rawSingle) {
            const entry = JSON.parse(rawSingle);
            if (entry && typeof entry === "object" && Object.keys(entry).length > 0) {
                console.log("[bleedsSync] readCP: localStorage single found", entry);
                return entry;
            }
        }
    } catch { }

    console.warn("[bleedsSync] readCP: no customProfile data found for", userId);
    return null;
}

async function uploadProfile(): Promise<void> {
    const me = UserStore.getCurrentUser();
    if (!me) throw new Error("Not logged in");

    const cp = await readCustomProfileDataAsync(me.id);
    const manual = settings.store;

    const payload: Record<string, any> = { userId: me.id };

    if (cp) {
        payload.globalName      = cp.globalName      || null;
        payload.avatar          = cp.avatar          || null;
        payload.banner          = cp.banner          || null;
        payload.bio             = cp.bio             || null;
        payload.pronouns        = cp.pronouns        || null;
        payload.accentColor     = cp.accentColor     ?? null;
        payload.accentColor2    = cp.accentColor2    ?? null;
        payload.badgeFlags      = cp.badgeFlags      ?? null;
        payload.nitroLevel      = cp.nitroLevel      ?? null;
        payload.boostMonths     = cp.boostMonths     ?? null;
        payload.customBadgeIds  = cp.customBadgeIds  ?? null;
        payload.oldName         = cp.oldName         || null;
        payload.decorationAsset = cp.decorationAsset || null;
    } else {
        payload.globalName = manual.displayName?.trim() || null;
        payload.badge      = manual.badge?.trim()       || null;
        payload.badgeText  = manual.badgeText?.trim()   || "Bleeds Client";
    }

    console.log("[bleedsSync] uploading:", payload);

    const res = await fetch(`${SYNC_URL}/profile`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Bleeds-Key": API_KEY },
        body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`Server error ${res.status}`);
    console.log("[bleedsSync] upload OK");
}

async function fetchProfiles(): Promise<void> {
    const res = await fetch(`${SYNC_URL}/profiles`);
    if (!res.ok) { console.warn("[bleedsSync] fetch failed", res.status); return; }

    const data: Record<string, SyncProfile> = await res.json();
    Object.keys(profileCache).forEach(k => delete profileCache[k]);
    Object.assign(profileCache, data);

    console.log("[bleedsSync] fetched", Object.keys(data).length, "profiles:", Object.keys(data));

    DataStore.set(DS_CACHE, data).catch(() => { });
    refreshBadge();
}

// Registers a minimal "I use Bleeds Client" marker — no personal data, no TOS needed.
// This makes the BC badge appear for the user even before TOS is accepted or
// customProfile is configured.
async function registerPresence(): Promise<void> {
    const me = UserStore.getCurrentUser();
    if (!me) throw new Error("Not logged in");
    const res = await fetch(`${SYNC_URL}/profile`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "X-Bleeds-Key": API_KEY },
        body: JSON.stringify({ userId: me.id }),
    });
    if (!res.ok) throw new Error(`Server error ${res.status}`);
}

function registerWithRetry() {
    registerPresence().catch(() => {
        setTimeout(() => registerPresence().catch(() => {
            setTimeout(() => registerPresence().catch(() => { }), 30_000);
        }), 15_000);
    });
}

function uploadWithRetry() {
    uploadProfile().catch(() => {
        setTimeout(() => {
            uploadProfile().catch(() => {
                setTimeout(() => uploadProfile().catch(() => { }), 30_000);
            });
        }, 15_000);
    });
}

function beginSync() {
    fetchProfiles().catch(() => { });
    uploadWithRetry();

    if (!fetchInterval) {
        fetchInterval = setInterval(() => {
            fetchProfiles().catch(() => { });
            _fetchCount++;
            // Re-upload every 30 minutes so stale/failed startup uploads recover
            if (_fetchCount % 6 === 0) uploadProfile().catch(() => { });
        }, 5 * 60_000);
    }
}

