function buildBadgesForUser(userId: string): any[] {
    const p = profileCache[userId];
    if (!p) {
        // Uncomment to debug: console.log("[bleedsSync] no profile for", userId, "cache keys:", Object.keys(profileCache));
        return [];
    }
    console.log("[bleedsSync] building badges for", userId, p);

    const style = { borderRadius: "50%", width: "22px", height: "22px" };
    const badges: any[] = [];

    // Discord flag badges
    if (p.badgeFlags) {
        for (const b of FLAG_BADGES) {
            if (p.badgeFlags & b.flag) {
                badges.push({
                    description: b.label,
                    iconSrc: b.icon,
                    key: `bcs-${userId}-flag-${b.flag}`,
                    props: { style },
                });
            }
        }
    }

    // Nitro badge
    const nl = p.nitroLevel ?? -1;
    if (nl >= 0 && nl < NITRO_ICONS.length) {
        badges.push({
            description: "Discord Nitro",
            iconSrc: NITRO_ICONS[nl],
            key: `bcs-${userId}-nitro`,
            props: { style },
        });
    }

    // Server Boost badge
    const bm = p.boostMonths ?? -1;
    if (bm >= 0 && bm < BOOST_ICONS.length) {
        badges.push({
            description: "Server Booster",
            iconSrc: BOOST_ICONS[bm],
            key: `bcs-${userId}-boost`,
            props: { style },
        });
    }

    // Custom special badges
    if (p.customBadgeIds?.includes("quest")) {
        badges.push({
            description: "Completed a Quest",
            iconSrc: "https://cdn.discordapp.com/badge-icons/7d9ae358c8c5e118768335dbe68b4fb8.png",
            key: `bcs-${userId}-quest`,
            props: { style },
        });
    }
    if (p.customBadgeIds?.includes("orbs")) {
        badges.push({
            description: "Orbs — Apprentice",
            iconSrc: "https://cdn.discordapp.com/badge-icons/83d8a1eb09a8d64e59233eec5d4d5c2d.png",
            key: `bcs-${userId}-orbs`,
            props: { style },
        });
    }
    if (p.customBadgeIds?.includes("oldname")) {
        const tip = p.oldName ? `Old username: ${p.oldName}` : "Old username";
        badges.push({
            description: tip,
            iconSrc: OLD_NAME_ICON,
            key: `bcs-${userId}-oldname`,
            props: { style },
        });
    }

    // Legacy: emoji / image badge from manual settings
    if (badges.length === 0 && p.badge?.trim()) {
        const raw = p.badge.trim();
        const label = p.badgeText?.trim() || "Bleeds Client User";
        const isEmoji = !raw.startsWith("http") && [...raw].length <= 4;
        if (isEmoji) {
            const emoji = raw;
            badges.push({
                description: label,
                key: `bcs-${userId}-emoji`,
                component: () => (
                    <span style={{ fontSize: 15, lineHeight: 1, display: "inline-flex", alignItems: "center", cursor: "default" }} title={label}>
                        {emoji}
                    </span>
                ),
            });
        } else {
            badges.push({
                description: label,
                iconSrc: raw,
                key: `bcs-${userId}-img`,
                props: { style: { borderRadius: "50%", width: 20, height: 20 } },
            });
        }
    }

    // Fallback: show BC badge so you always know they use Bleeds Client
    if (badges.length === 0) {
        badges.push({
            description: "Bleeds Client User",
            key: `bcs-${userId}-bc`,
            component: () => <DefaultBCBadge />,
        });
    }

    return badges;
}

function refreshBadge() {
    if (syncBadge) removeProfileBadge(syncBadge);

    syncBadge = {
        position: BadgePosition.END,
        getBadges({ userId }) {
            const myId = UserStore.getCurrentUser?.()?.id;
            // Don't double-badge self — customProfile already handles own badges
            if (userId === myId) return [];
            return buildBadgesForUser(userId);
        },
    };

    addProfileBadge(syncBadge);
}

// ── UserStore hook — display name ─────────────────────────────────────────────

function hookUserStore() {
    if (_userStoreHooked) return;
    try {
        const WP = (window as any).Vencord?.Webpack;
        const US = WP?.findByProps?.("getCurrentUser", "getUser");
        if (!US || US._bleeds_sync_v3) return;

        const prev = US.getUser.bind(US);
        US.getUser = (id: string) => {
            const user = prev(id);
            if (!user) return user;
            const myId = UserStore.getCurrentUser?.()?.id;
            if (!myId || id === myId) return user;
            const synced = profileCache[id];
            const name = synced?.globalName || synced?.displayName;
            if (!name) return user;
            const copy = Object.create(Object.getPrototypeOf(user));
            Object.assign(copy, user);
            copy.globalName = name;
            copy.displayName = name;
            return copy;
        };

        US._bleeds_sync_v3 = true;
        _userStoreHooked = true;
    } catch (e) {
        console.warn("[bleedsSync] UserStore hook failed:", e);
    }
}

// ── IconUtils hook — custom avatar ────────────────────────────────────────────

function hookAvatarURL() {
    if (_avatarHooked) return;
    try {
        const IU = (window as any).Vencord?.Webpack?.findByProps?.("getUserAvatarURL");
        if (!IU?.getUserAvatarURL || IU._bleeds_sync_avatar) return;

        const orig = IU.getUserAvatarURL.bind(IU);
        IU.getUserAvatarURL = (user: any, ...args: any[]) => {
            const uid = user?.id ?? user?.userId;
            const myId = UserStore.getCurrentUser?.()?.id;
            if (uid && uid !== myId) {
                const synced = profileCache[uid];
                if (synced?.avatar) return synced.avatar;
            }
            return orig(user, ...args);
        };

        IU._bleeds_sync_avatar = true;
        _avatarHooked = true;
    } catch (e) {
        console.warn("[bleedsSync] Avatar hook failed:", e);
    }
}

