// ── Plugin ─────────────────────────────────────────────────────────────────────

export default definePlugin({
    name: "bleedsSync",
    description: "Shares your Custom Profile (badges, name, avatar) with other Bleeds Client users in real time.",
    authors: [{ name: "Bleeds Client", id: 0n }],
    settings,
    required: true,

    async start() {
        // Expose for DevTools debugging: run `__bleedsSync.cache` in Discord console
        (window as any).__bleedsSync = { cache: profileCache, upload: uploadProfile, fetch: fetchProfiles };

        const cached = await DataStore.get(DS_CACHE) as Record<string, SyncProfile> | null;
        if (cached && typeof cached === "object") Object.assign(profileCache, cached);

        refreshBadge();
        hookUserStore();
        hookAvatarURL();

        // Patch DataStore.set so saving customProfile triggers an immediate re-upload
        if (!_dsPatched) {
            const origSet = (DataStore as any).set.bind(DataStore);
            (DataStore as any).set = async (key: string, value: any) => {
                const result = await origSet(key, value);
                if (key === CP_DS_ALL_DATA || key === CP_DS_KEY) {
                    // CustomProfile just saved — re-upload after a short delay
                    setTimeout(() => uploadProfile().catch(() => { }), 800);
                }
                return result;
            };
            _dsPatched = true;
        }

        // Always register presence — no TOS needed, just marks this user as a BC user
        registerWithRetry();

        const agreed = await DataStore.get(DS_TOS);

        // start() runs before Discord's UI is ready, so openModal() silently fails
        // if called immediately. Use CONNECTION_OPEN as the trigger, with a 5s
        // timeout as a guaranteed fallback.
        let _ready = false;
        const onReady = () => {
            if (_ready) return;
            _ready = true;
            if (agreed) {
                beginSync();
            } else {
                openTosModal(
                    async () => {
                        await DataStore.set(DS_TOS, true);
                        beginSync();
                    },
                    () => { },
                );
            }
        };

        try {
            const handler = () => {
                try { FluxDispatcher.unsubscribe("CONNECTION_OPEN", handler); } catch { }
                onReady();
            };
            FluxDispatcher.subscribe("CONNECTION_OPEN", handler);
        } catch { }

        // Fallback: fire after 5 s even if CONNECTION_OPEN never arrives
        setTimeout(onReady, 5000);
    },

    stop() {
        if (fetchInterval) { clearInterval(fetchInterval); fetchInterval = null; }
        if (syncBadge) { removeProfileBadge(syncBadge); syncBadge = null; }
        _fetchCount = 0;
    },
});
